#!/usr/bin/env python3
"""Generate the original CC0 Hyprune development atrium. No external assets."""
import json, math, pathlib, struct, zlib
root = pathlib.Path(__file__).parent / 'atrium'
root.mkdir(exist_ok=True)
blob = bytearray(); views=[]; accessors=[]; meshes=[]; nodes=[]
materials = [
 {'name':'slate', 'pbrMetallicRoughness':{'baseColorFactor':[.12,.19,.23,1]}},
 {'name':'walkway', 'pbrMetallicRoughness':{'baseColorFactor':[.35,.45,.45,1]}},
 {'name':'pale concrete', 'pbrMetallicRoughness':{'baseColorFactor':[.62,.69,.67,1]}},
 {'name':'copper', 'pbrMetallicRoughness':{'baseColorFactor':[.47,.23,.1,1]}},
 {'name':'mint light', 'pbrMetallicRoughness':{'baseColorFactor':[.05,.4,.29,1]},'emissiveFactor':[.1,.9,.6]},
 {'name':'blue light', 'pbrMetallicRoughness':{'baseColorFactor':[.05,.2,.45,1]},'emissiveFactor':[.12,.4,1]},
]
vertices=[[] for _ in materials]
def quad(a,b,c,d,mat):
    for p,uv in [(a,(0,0)),(b,(1,0)),(c,(1,1)),(a,(0,0)),(c,(1,1)),(d,(0,1))]:
        vertices[mat].append((*p,*uv))
def box(x,y,z,w,h,d,mat):
    a=(x-w/2,y,z-d/2);b=(x+w/2,y,z-d/2);c=(x+w/2,y+h,z-d/2);e=(x-w/2,y+h,z-d/2)
    f=(a[0],y,z+d/2);g=(b[0],y,z+d/2);i=(b[0],y+h,z+d/2);j=(a[0],y+h,z+d/2)
    for points in [(f,g,i,j),(b,a,e,c),(a,f,j,e),(g,b,c,i),(j,i,c,e),(a,b,g,f)]:quad(*points,mat)
for x in range(-7,7):
    for z in range(-15,9):
        box(x+.5,-.15,z+.5,.985,.15,.985,1 if abs(x)<2 else 0)
# perimeter, columns, beams, low plinths
box(-7,0,-3,.4,5,24,2);box(7,0,-3,.4,5,24,2);box(0,0,-15,14,5,.4,2);box(0,0,9,14,3,.4,2)
for z in [-12,-7,-2,3,8]:
    for x in [-5.8,5.8]:
        box(x,0,z,.5,4.8,.5,3);box(x,4.3,z,.8,.2,.8,4)
    box(0,4.65,z,12.3,.25,.3,2)
for x in [-4,4]:
    box(x,0,-10,2,.6,2,2)
    for j in range(5):box(x+(j-2)*.23,.6,-10,.13,1.3+math.sin(j)*.3,.13,4 if x<0 else 5)
box(0,1,-14.7,5,.06,.06,4);box(0,2,-14.7,5,.06,.06,5)
# each material is one glTF node, all have explicit collision metadata
for material,verts in enumerate(vertices):
    positions=[v[:3] for v in verts];uv=[v[3:] for v in verts]
    attributes={}
    for semantic,values,components in [('POSITION',positions,3),('TEXCOORD_0',uv,2),('TEXCOORD_1',uv,2)]:
        while len(blob)%4:blob.append(0)
        offset=len(blob)
        for v in values:blob.extend(struct.pack('<'+'f'*components,*v))
        views.append({'buffer':0,'byteOffset':offset,'byteLength':len(blob)-offset})
        accessor={'bufferView':len(views)-1,'componentType':5126,'count':len(values),'type':'VEC'+str(components)}
        if semantic=='POSITION':
            accessor['min']=[min(p[c] for p in positions) for c in range(3)];accessor['max']=[max(p[c] for p in positions) for c in range(3)]
        accessors.append(accessor);attributes[semantic]=len(accessors)-1
    meshes.append({'name':materials[material]['name'],'primitives':[{'attributes':attributes,'material':material,'mode':4}]})
    nodes.append({'mesh':len(meshes)-1})
def png(path):
    def chunk(t,d):return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    # Constant atlas: same irradiance at every texel; UV overlap is deliberate for this test swatch.
    data=b''.join(b'\x00'+bytes([210,225,240,255])*4 for _ in range(4))
    path.write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',4,4,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(data))+chunk(b'IEND',b''))
png(root/'irradiance.png')
gltf={'asset':{'version':'2.0','generator':'Hyprune original procedural fixture'},'scene':0,'scenes':[{'nodes':list(range(len(nodes)))}],'nodes':nodes,'meshes':meshes,'materials':materials,'buffers':[{'uri':'geometry.bin','byteLength':len(blob)}],'bufferViews':views,'accessors':accessors,'images':[{'uri':'irradiance.png'}],'textures':[{'source':0}]}
(root/'geometry.bin').write_bytes(blob);(root/'scene.gltf').write_text(json.dumps(gltf))
manifest={'formatVersion':'0.1','id':'org.hyprune.atrium','version':'0.0.1','name':'The First Atrium','description':'An original procedural room for Hyprune runtime tests.','license':'CC0-1.0','scene':'scene.gltf','defaultSpawn':'entry','spawns':[{'id':'entry','pose':{'position':[0,0,4],'rotation':[0,0,0,1]}}],'collision':[{'node':i,'shape':'mesh','layer':'static'} for i in range(len(nodes))],'lightmaps':[{'material':0,'texture':0,'texCoord':1,'encoding':'linear','intensity':1}],'attribution':[{'path':'.','author':'Hyprune contributors','license':'CC0-1.0','source':'https://creativecommons.org/publicdomain/zero/1.0/'}]}
(root/'world.json').write_text(json.dumps(manifest,indent=2)+'\n')
(root/'LICENSE').write_text('Original procedural assets dedicated to the public domain under CC0 1.0.\nhttps://creativecommons.org/publicdomain/zero/1.0/\n')
(root/'ATTRIBUTION.md').write_text('All geometry and the constant irradiance texture are generated by ../generate.py.\nAuthor: Hyprune contributors. License: CC0-1.0. No third-party assets.\n')
print(root)
